-- 009: სათამაშოების ახალი, ორსართულიანი სახელები (16.11.2026):
-- სახელი + ზუსტი აღწერა, ახალი ტექსტები, „რას ავითარებს“, ასაკი, კატეგორიების ახალი სახელები.
-- სათამაშოს მონაცემები: [სახელი, ტექსტი, მასალა, ზომა, აღწერა, რას ავითარებს, ასაკი].
-- მეორედ გაშვება არაფერს აფუჭებს: იგივე მნიშვნელობებს ისევ წერს.

update settings s
set value = jsonb_set(s.value, '{products}', (
      select jsonb_agg(
               case when v.id is not null then jsonb_set(jsonb_set(t.p, '{ka}', v.ka), '{en}', v.en) else t.p end
               order by t.ord)
      from jsonb_array_elements(s.value->'products') with ordinality as t(p, ord)
      left join (values
    ('toolbox', '["ოსტატი", "პატარა ოსტატს საკუთარი ყუთი სჭირდება. შიგნით არის ჩაქუჩი, ქანჩის გასაღები, სახაზავი და სათამაშო ბურღი. ხრახნები და ფირფიტები ერთმანეთს უერთდება, ასე რომ ბავშვი თავად აწყობს მანქანას, თვითმფრინავს ან რასაც მოიფიქრებს.", "ხე; ბურღი და ხრახნები პლასტმასისაა", "", "ხის ხელსაწყოების ყუთი ბურღით", "✋ წვრილი მოტორიკა · 🧩 აწყობა და ფანტაზია · 🛠 ხელსაწყოების გაცნობა", "3+ წელი"]'::jsonb, '["Little Builder", "Every little builder needs a box of their own. Inside: a hammer, a wrench, a ruler and a toy drill. Bolts and plates join together, so a child builds a car, a plane or anything they think up.", "Wood; plastic drill and bolts", "", "Wooden tool box with a toy drill", "✋ Fine motor skills · 🧩 Building and imagination · 🛠 Getting to know tools", "3+ years"]'::jsonb),
    ('music', '["ორკესტრი", "მთელი ორკესტრი ერთ მაგიდაზე: ორი დოლი, ქსილოფონი, თეფში, ზარი და ზანზალაკები. ჯოხები თავის ბუდეებში ინახება, რომ შემდეგ კონცერტამდე არ დაიკარგოს.", "ხე; ლითონის დეტალები", "", "მუსიკალური მაგიდა: დოლები, ქსილოფონი, ზარები", "🎵 რიტმი და სმენა · ✋ ხელების კოორდინაცია · 💡 მიზეზი და შედეგი", "1+ წელი"]'::jsonb, '["Little Orchestra", "A whole orchestra on one table: two drums, a xylophone, a cymbal, a bell and chimes. The sticks rest in their own holders, so they don''t get lost before the next concert.", "Wood; metal parts", "", "Music table: drums, xylophone, bells", "🎵 Rhythm and listening · ✋ Hand coordination · 💡 Cause and effect", "1+ years"]'::jsonb),
    ('train', '["ექსპრესი", "ყოველ ჯერზე ახალი მარშრუტი. ხის ლიანდაგი ორ დონეზე ეწყობა, ხიდით, გვირაბით და მატარებლით, ნაწილები კი სხვადასხვანაირად ერთდება.", "ხის ლიანდაგი; ხიდი და საყრდენები პლასტმასისაა", "", "ორსართულიანი ხის რკინიგზა ხიდით და გვირაბით", "🧩 სივრცითი აზროვნება · 🛤 დაგეგმვა და აწყობა · 🎭 ისტორიების გამოგონება", "3+ წელი"]'::jsonb, '["Express", "A new route every time. The wooden track builds on two levels, with a bridge, a tunnel and a train, and the pieces fit together in different ways.", "Wooden track; plastic bridge and supports", "", "Two-level wooden railway with a bridge and a tunnel", "🧩 Spatial thinking · 🛤 Planning and building · 🎭 Making up stories", "3+ years"]'::jsonb),
    ('walker', '["პირველი ნაბიჯი", "ჯერ პირველ ნაბიჯებში ეხმარება, მერე პირველ „სადილებში“. სასიარულო ურიკა, რომელიც თან სამზარეულოა: ქვაბი, ტაფა, ღუმელი და გვერდებზე სათამაშო პანელები.", "ხე", "45.5 × 35 × 31 სმ", "სასიარულო ურიკა-სამზარეულო", "🚶 სიარული და წონასწორობა · ✋ წვრილი მოტორიკა · 🎭 როლური თამაში", "1+ წელი"]'::jsonb, '["First Steps", "First it helps with the first steps, then with the first \"dinners\". A push walker that is also a kitchen: a pot, a pan, an oven and activity panels on the sides.", "Wood", "45.5 × 35 × 31 cm", "Kitchen push walker", "🚶 Walking and balance · ✋ Fine motor skills · 🎭 Pretend play", "1+ years"]'::jsonb),
    ('radio', '["რეტრო", "ყველა ღილაკი რაღაცას აკეთებს, და ბავშვი სწორედ ამას აღმოაჩენს. ძველი მაგნიტოფონის მსგავს ხის დაფაზეა ჩამრთველები, სახელურები, ნათურები, ხმის ჩამწერი, 5 სიმღერა გადასართავად, მძივების ლაბირინთი და დახატული პიანინოს კლავიშები. აქვს ტარების სახელური.", "ხე; ნათურები და ღილაკები", "", "მაგნიტოფონის ბიზიბორდი: ნათურები, მელოდიები, ხმის ჩამწერი", "💡 მიზეზი და შედეგი · ✋ წვრილი მოტორიკა · 🎵 სმენა", "1+ წელი"]'::jsonb, '["Retro", "Every button does something, and that is exactly what a child discovers. A wooden board styled like an old tape recorder: switches, knobs, lights, a voice recorder, 5 songs to switch between, a bead maze and printed piano keys. Has a carrying handle.", "Wood; lights and buttons", "", "Tape recorder busy board: lights, melodies, voice recorder", "💡 Cause and effect · ✋ Fine motor skills · 🎵 Listening", "1+ years"]'::jsonb),
    ('vanity', '["სარკე-სარკე", "ყველაფერი ისე, როგორც დედას აქვს, ოღონდ ხისგან. მაგიდაა სარკით, ფენით, სავარცხლით, სუნამოთი და ფრჩხილის ლაქით.", "ხე", "დაახლ. 30.5 × 21 × 21 სმ", "ხის სატუალეტო მაგიდა სარკით და აქსესუარებით", "🎭 როლური თამაში · 💬 მეტყველება და ისტორიები · ✋ წვრილი მოტორიკა", "3+ წელი"]'::jsonb, '["Mirror Mirror", "Everything just like mum''s, only made of wood. A table with a mirror, a hairdryer, a comb, perfume and nail polish.", "Wood", "approx. 30.5 × 21 × 21 cm", "Wooden vanity table with mirror and accessories", "🎭 Pretend play · 💬 Language and storytelling · ✋ Fine motor skills", "3+ years"]'::jsonb),
    ('vet', '["ჰავ-ჰავის კლინიკა", "ლეკვს ექიმი სჭირდება! ნაკრებშია ხის სახლი სახელურით, რბილი ძაღლი და ექიმის ხელსაწყოები: სტეტოსკოპი, შპრიცი, თერმომეტრი და მაკრატელი.", "ხე; რბილი სათამაშო ძაღლი", "", "ვეტერინარის ნაკრები რბილი ლეკვით", "❤️ ზრუნვა და ემპათია · 🎭 როლური თამაში · 💬 მეტყველება", "3+ წელი"]'::jsonb, '["Puppy Clinic", "The puppy needs a doctor! A wooden house with a handle, a soft dog and doctor''s tools: a stethoscope, a syringe, a thermometer and scissors.", "Wood; soft toy dog", "", "Vet set with a soft puppy", "❤️ Care and empathy · 🎭 Pretend play · 💬 Language", "3+ years"]'::jsonb),
    ('table', '["აღმოჩენა", "ერთ მაგიდაზე ხუთი სხვადასხვა თამაშია, და ერთზე მეტი ბავშვი ეტევა. ნახევარმთვარის ფორმის მაგიდაზე არის მძივების ლაბირინთი, კბილანები, ფიგურების დასაწყობი, ქსილოფონი და სტაფილოების ბოსტანი.", "ხე", "", "განმავითარებელი მაგიდა: ლაბირინთი, კბილანები, სორტერი", "✋ წვრილი მოტორიკა · 🔺 ფორმები და ფერები · 👫 ერთად თამაში", "1+ წელი"]'::jsonb, '["Discovery", "Five different games on one table, with room for more than one child. A half-moon table with a bead maze, gears, a shape sorter, a xylophone and a carrot garden.", "Wood", "", "Activity table: bead maze, gears, shape sorter", "✋ Fine motor skills · 🔺 Shapes and colours · 👫 Playing together", "1+ years"]'::jsonb),
    ('tap', '["ბუმ-ბუმ", "ერთ ყუთში სამი თამაშია: ფიგურების ჩარტყმა ჩაქუჩით, ქსილოფონი და თევზაობა ანკესით. ენერგიისთვისაც და სიმშვიდისთვისაც.", "ხე", "", "3-ში-1: ჩაქუჩის თამაში, ქსილოფონი, თევზაობა", "🎯 ხელისა და თვალის კოორდინაცია · 🎵 რიტმი · 🧘 მოთმინება და კონცენტრაცია", "2+ წელი"]'::jsonb, '["Boom-Boom", "Three games in one box: whack the figures with a hammer, play the xylophone and go fishing with a rod. For energetic moments and calm ones.", "Wood", "", "3-in-1: hammer game, xylophone, fishing", "🎯 Hand-eye coordination · 🎵 Rhythm · 🧘 Patience and focus", "2+ years"]'::jsonb),
    ('driver', '["პატარა მძღოლი", "საჭე ხელში და მივდივართ! ერთ ხის დაფაზეა საჭე, სიჩქარის გადამრთველი, მაჩვენებლები, ნათურები და ღილაკები.", "ხე; ნათურები და ჩამრთველები", "", "საჭის ბიზიბორდი: ჩამრთველები, ნათურები", "💡 მიზეზი და შედეგი · ✋ წვრილი მოტორიკა · 🎭 წარმოსახვა", "1+ წელი"]'::jsonb, '["Little Driver", "Hands on the wheel and off we go! A steering wheel, a gear lever, dials, lights and buttons on one wooden board.", "Wood; lights and switches", "", "Steering wheel busy board: switches, lights", "💡 Cause and effect · ✋ Fine motor skills · 🎭 Imagination", "1+ years"]'::jsonb)
      ) as v(id, ka, en) on v.id = t.p->>'id'
    )),
    updated_at = now()
where s.key = 'shop' and jsonb_array_length(s.value->'products') > 0;

-- კატეგორიები, ახალი სიტყვები („ასაკი“, „რას ავითარებს“) და ოთახის სექციის ტექსტი
update settings
set value = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(value, '{T,ka,build}', '"ვაწყობთ და ვქმნით"'::jsonb), '{T,ka,music}', '"მუსიკა და ხმა"'::jsonb), '{T,ka,role}', '"ვთამაშობთ უფროსობანას"'::jsonb), '{T,ka,boards}', '"ბიზიბორდები და მაგიდები"'::jsonb), '{T,ka,age}', '"ასაკი"'::jsonb), '{T,ka,dev}', '"რას ავითარებს"'::jsonb), '{T,ka,roomText}', '"„{name}“ ჯერ სიარულში ეხმარება, მერე კი სამზარეულოდ რჩება. თამაშის შემდეგაც ოთახში ისე დგას, როგორც ავეჯის ნაწილი."'::jsonb), '{T,en,build}', '"Build & Create"'::jsonb), '{T,en,music}', '"Music & Sound"'::jsonb), '{T,en,role}', '"Pretend Play"'::jsonb), '{T,en,boards}', '"Busy Boards & Tables"'::jsonb), '{T,en,age}', '"Age"'::jsonb), '{T,en,dev}', '"What it develops"'::jsonb), '{T,en,roomText}', '"{name} first helps with walking, then stays on as a kitchen. After play it stands in the room like a piece of furniture."'::jsonb),
    updated_at = now()
where key = 'shop';
